// ── Lazy loader ────────────────────────────────────────────────────────────────
let _cache = null;         // full { [bankName]: [{ifsc,branch,city,state}] }
let _promise = null;       // in-flight fetch promise

/**
 * Returns a Promise that resolves to the full IFSC data map.
 * Data is fetched once from /bankData.json and cached in memory.
 */
export async function loadBankData() {
  if (_cache) return _cache;
  if (!_promise) {
    _promise = fetch('/bankData.json')
      .then(r => { if (!r.ok) throw new Error('Failed to load bank data'); return r.json(); })
      .then(data => { _cache = data; return data; });
  }
  return _promise;
}

/**
 * Returns a Promise that resolves to an array of { ifsc, branch, city, state }
 * for the given bank name.  Resolves to [] if bank not found.
 */
export async function getIFSCListForBank(bankName) {
  const data = await loadBankData();
  return data[bankName] || [];
}
